def _get_core_tagline(dm, ys):
    key = (dm.get('char', ''), ys.get('name', ''))
    tagline = CORE_IDENTITY_TAGLINES.get(key)
    if tagline:
        return tagline
    return _get_essence_sub(dm, ys)

