def _auto_integrated_insight(p):
    """narratives.yaml が無いユーザー向けに、4〜5段落の統合インサイトを自動生成。"""
    try:
        dm = p['four_pillars']['day_master']
        dm_char = dm.get('char', '')
        dm_element = dm.get('element', '')
        dm_yy = dm.get('yin_yang', '')
        ns = p['nine_star_ki']['year_star']
        ns_name = ns.get('name', '')
        rok = p['rokusei']['main_star']
        rok_name = rok.get('name', '')
        reigou = p['rokusei'].get('reigou', False)
        sun_sign = p['western_astrology']['sun_sign'].get('sign', '')
        animal = p['four_pillars']['year_pillar']['branch'].get('animal', '')
        animal_ja = {'Rat':'子','Ox':'丑','Tiger':'寅','Rabbit':'卯','Dragon':'辰','Snake':'巳',
                     'Horse':'午','Goat':'未','Monkey':'申','Rooster':'酉','Dog':'戌','Pig':'亥'}.get(animal, animal)
        bt = p.get('blood_type', {}).get('type', '')
        missing = p['four_pillars'].get('missing_elements', [])
        name = p.get('identity', {}).get('name', 'あなた')
        age = p.get('identity', {}).get('age', 0)
        sex = p.get('identity', {}).get('sex', '')

        dm_story = DM_NARRATIVE_LONG.get(dm_char, '')
        ns_story = NS_NARRATIVE.get(ns_name, '')
        rok_story = ROKUSEI_NARRATIVE.get(rok_name, '')
        sun_story = WESTERN_NARRATIVE.get(sun_sign, '')
        bt_story = BT_NARRATIVE_LONG.get(bt, '')
        eto_story = ETO_GIST.get(animal, '')

        # 年齢層別の開口一番 (p0) — 70歳以上は人生集大成、40-60代は転換期
        p0 = None
        if age >= 70:
            cur9 = next((c for c in p['nine_star_ki'].get('nine_year_cycle', []) if c.get('current')), None)
            cur12 = next((c for c in p['rokusei'].get('twelve_year_cycle', []) if c.get('current')), None)
            if cur9 and cur12 and cur9['energy'] >= 80 and cur12['energy'] >= 80:
                p0 = (f'{name}さん、{age}年という人生のすべてが、今このダッシュボードの言葉に凝縮されています。'
                      f'占いは「未来を当てるもの」ではなく、<strong>「あなたが歩んできた道を肯定するもの」</strong>でもあります。'
                      f'今年は九星気学で<strong>{cur9["palace"]}（{cur9["theme"]}）</strong>、六星占術で<strong>{cur12["phase"]}</strong>——'
                      f'複数の体系が口を揃えて「今年が実りの時」と告げています。'
                      f'これまでの努力と選択は、正しかったのです。')
            else:
                p0 = (f'{name}さん、{age}年という人生の積み重ねが、あなたの命式の深みとなって輝いています。'
                      f'占いの言葉は、あなたが経験してきたことをただ映し出す鏡です。'
                      f'ここに書かれている強みも、気を付けるべき点も、すべて<strong>あなたが既に知っていること</strong>のはずです。')
        elif 40 <= age < 60:
            cur9 = next((c for c in p['nine_star_ki'].get('nine_year_cycle', []) if c.get('current')), None)
            cur_comb = next((c for c in p['rokusei'].get('reigou_combined', []) if c.get('year') == 2026), None)
            if reigou and cur_comb and cur_comb['score'] < 50:
                # 霊合矛盾期の特別メッセージ
                p0 = (f'{name}さん、今あなたの中に「なぜこんなに頑張っているのにうまくいかない」という感覚はありませんか。'
                      f'それは気のせいでも、あなたの責任でもありません。'
                      f'霊合星人のあなたは今年、<strong>2つの運命星が正反対のことを言っている時期</strong>に入っています。'
                      f'主星は「達成せよ」と言い、副星は「立ち止まれ」と言う——その矛盾が、あなたの疲れの根本にあります。'
                      f'矛盾を感じているなら、それはあなたのセンサーが正常に機能している証拠です。')
            elif cur9 and cur9['energy'] <= 40:
                p0 = (f'{name}さん、{age}歳というのは、「これまでの自分」と「これからの自分」が静かに入れ替わる時期です。'
                      f'今年は九星気学で<strong>{cur9["palace"]}（{cur9["theme"]}）</strong>に位置し、外へ向かうエネルギーより、'
                      f'<strong>内側を見直すエネルギー</strong>の方が大きい時期にあたります。'
                      f'停滞に感じるものは、実は次のフェーズへの準備です。')

        # 段1: 日主 + 本命星 + 血液型
        p1 = f'''{name}さんを一言で言い表すなら、四柱推命の日主が示す「<strong>{dm_char}日主</strong>」——{dm_story} そして、九星気学の本命星から見える社会に出た時のお顔は「<strong>{ns_name}</strong>」——{ns_story} 血液型は「<strong>{bt}型</strong>」で、{bt_story}。生年月日という揺るぎない事実だけから、{name}さんの核はこのように浮かび上がります。'''

        # 段2: 西洋占星術 + 干支
        p2 = f'''視点を変えて西洋占星術で見ると、あなたは <strong>{sun_story}</strong>。東洋の干支に目を向けると <strong>{animal_ja}年（{eto_story}）</strong>でいらっしゃいます。起源の全く違う 2 つの体系が、あなたの気質を別々の角度から描き出しているのです。東洋と西洋の読みが重なり合う場所に、<strong>「本当に変わらないあなたの軸」</strong>が静かに見えてまいります。'''

        # 段3: 六星占術 (+ 霊合)
        if reigou:
            sub_star = p['rokusei'].get('sub_star', {})
            sub_name = sub_star.get('name', '') if sub_star else ''
            if sub_name:
                p3 = (f'さらに六星占術の視点を加えますと、あなたは <strong>{rok_name}（霊合星人）</strong>でいらっしゃいます。{rok_story} '
                      f'霊合星人は日本人口のわずか 15% しかいない希少な体質で、あなたの場合は <strong>{rok_name}</strong> と <strong>{sub_name}</strong> の2つの運命星を同時に宿しています。'
                      f'<strong>運気の振れ幅が一般の 2 倍</strong>——好調の時期は抜きん出て輝き、不調の時期は深く沈む。'
                      f'それはあなたが「普通の人生」ではなく、<strong>ドラマのある人生を生きている証</strong>でもあります。')
            else:
                p3 = f'''さらに六星占術の視点を加えますと、あなたは <strong>{rok_name}（霊合星人）</strong>でいらっしゃいます。{rok_story} 霊合星人は日本人口のわずか 15% しかいない希少な体質で、2 つの運命星を同時に宿すため <strong>運気の振れ幅が一般の 2 倍</strong>と言われております。好調の時期は抜きん出て、不調の時期は深く沈む——そんなダイナミックなリズムが、あなたの人生を形作っていらっしゃるのです。'''
        else:
            p3 = f'''六星占術の視点を加えると、あなたは <strong>{rok_name}</strong>でいらっしゃいます。{rok_story} 12 年周期で運気が巡るため、「今の時期になさるべきこと・お控えになるべきこと」が明確に見えてくるのが、この体系ならではの強みでございます。'''

        # 段4: 欠けている五行 + 運用アドバイス
        if missing:
            miss_str = '・'.join(missing)
            miss_action = {
                '木':'挑戦や拡張の行動',
                '火':'情熱を込めた発信・人前に出る場面',
                '土':'腰を据えた継続・コツコツ積み上げる時間',
                '金':'決断と手放すこと・期限を設けること',
                '水':'流動性・休息・柔軟にお受けになる姿勢',
            }
            miss_meaning = {
                '木':'成長力・拡張・新しいスタート',
                '火':'情熱・行動力・人前に出る力',
                '土':'継続力・安定・地道な積み上げ',
                '金':'決断力・収穫・区切りをつける力',
                '水':'知恵・柔軟性・流れに乗る力',
            }
            actions = '、'.join(miss_action.get(m, '') for m in missing if m in miss_action)
            meanings = '、'.join(f'「{miss_meaning.get(m, m)}」' for m in missing if m in miss_meaning)
            p4 = (f'最後に、お気を付けいただきたい点を一つ。あなたの命式で欠けている五行は「<strong>{miss_str}</strong>」でいらっしゃいます。'
                  f'これは {meanings} のエネルギーが命式から出づらい構造であることを示しています。'
                  f'「弱点」ではなく、「<strong>意識的に補うと、全体のバランスが整う方向</strong>」とお考えください。'
                  f'自然体では{actions}が後回しになりがちですので、'
                  f'予定や環境を整える形で仕組みになさると、あなたの本来の強みが最大限に活きてまいります。')
        else:
            p4 = f'''五行の分布は美しくバランスが取れています。特定の要素が突出することも、欠けることもない整った命式でいらっしゃいます。言い換えますと、<strong>「どの方向にも振れる柔軟性」</strong>をお持ちで、状況に応じて様々なモードを自然に使い分けていかれるタイプの方です。'''

        paragraphs = [p1, p2, p3, p4]
        if p0:
            paragraphs = [p0] + paragraphs
        return paragraphs
    except Exception as e:
        return [f'統合インサイトの自動生成に失敗: {e}']

def _core_identity(p):
    dm = p['four_pillars']['day_master']
    ys = p['nine_star_ki']['year_star']
    missing = p['four_pillars'].get('missing_elements', [])
    interp = p.get('interpretations', {})

    # Integrated insight box — first paragraph visible, rest collapsed
    insight_paras = interp.get('integrated_insight', [])
    # narratives.yaml が無いユーザー向けのフォールバック: プロファイルから自動生成
    if not insight_paras:
        insight_paras = _auto_integrated_insight(p)
    insight_html = ''
    if insight_paras:
        first_p = f'<p style="line-height:1.9;font-size:14px;">{insight_paras[0]}</p>'
        if len(insight_paras) > 1:
            rest_ps = ''.join(f'<p style="line-height:1.9;font-size:14px;margin-top:12px;">{para}</p>'
                              for para in insight_paras[1:])
            insight_html = f'''<div class="insight-box" style="border-left-color:#4F46E5">
    <div class="insight-title" style="font-size:15px;">統合インサイト</div>
    {first_p}
    <div class="collapsible-content" style="display:none">{rest_ps}</div>
    <button class="collapse-toggle" onclick="this.previousElementSibling.style.display=this.previousElementSibling.style.display==='none'?'block':'none';this.textContent=this.previousElementSibling.style.display==='none'?'続きを読む':'閉じる'">続きを読む</button>
  </div>'''
        else:
            insight_html = f'''<div class="insight-box" style="border-left-color:#4F46E5">
    <div class="insight-title" style="font-size:15px;">統合インサイト</div>
    {first_p}
  </div>'''

    # Dynamic summary cards
    dm_desc = dm.get('description', '')
    # Core Essence
    yin_yang_ja = {'Yin':'陰','Yang':'陽'}.get(dm.get('yin_yang',''), '')
    elem_ja = {'Fire':'火','Wood':'木','Earth':'土','Metal':'金','Water':'水'}.get(dm.get('element',''), '')
    essence_value = f'{dm["char"]}{elem_ja} × {ys["name"]}'
    essence_sub = _get_essence_sub(dm, ys)

    # Strongest Axis
    sf_top5 = p.get('strengths_finder', {}).get('top5', [])
    if sf_top5 and len(sf_top5) >= 2:
        t1_ja = SF_JA.get(sf_top5[0]['name'], sf_top5[0]['name'])
        t2_ja = SF_JA.get(sf_top5[1]['name'], sf_top5[1]['name'])
        axis_value = f'{t1_ja} × {t2_ja}'
        axis_sub = f'{sf_top5[0]["name"]}（{t1_ja}）+ {sf_top5[1]["name"]}（{t2_ja}）'
    else:
        # Fallback: 干支の気質 × 日主の本質
        animal_local = p['four_pillars']['year_pillar']['branch'].get('animal', '')
        eto_gist_local = ETO_GIST.get(animal_local, '')
        dm_char_local = dm.get('char', '')
        dm_gist_local = DM_GIST.get(dm_char_local, '')
        if eto_gist_local and dm_gist_local:
            axis_value = f'{eto_gist_local} × {dm_char_local}の本質'
            axis_sub = f'干支が示す気質 + 日主が示す判断軸'
        else:
            axis_value = '詳細は Tier 2 で'
            axis_sub = '性格アンケートで明確化'

    # Duality
    bt = p['blood_type']
    ennea = p.get('personality', {}).get('enneagram', {})
    rok = p['rokusei']
    etype = ennea.get('type', None)
    reigou = rok.get('reigou', False)
    # Tier 1 (エニアグラム未取得) は、霊合星人の有無で表現を変える
    if etype:
        if reigou:
            dual_sub = f'{bt["type"]}型 × 霊合星人 × エニアグラム Type {etype}'
        else:
            dual_sub = f'{bt["type"]}型 × エニアグラム Type {etype}'
    else:
        if reigou:
            dual_sub = f'{bt["type"]}型 × 霊合星人（二つの運命星）'
        else:
            dual_sub = f'{bt["type"]}型 × 陰陽のバランス'
    dual_value = _get_duality_value(bt, ennea, rok)

    # Watch Out
    if missing:
        missing_str = "・".join(str(m) for m in missing)
        watch_value = f'{missing_str}の欠如'
        watch_sub = _get_missing_sub(missing)
    else:
        watch_value = '—'
        watch_sub = ''

    tagline = _get_core_tagline(dm, ys)
    quote_html = f'<div class="section-quote">"あなたを一言で表すなら——{tagline}"</div>'

    dm_char = dm.get('char', '')
    ys_name = ys.get('name', '')
    rok_type = rok.get('main_star', {}).get('name', '') if 'main_star' in rok else ''
    dm_narr = DM_NARRATIVE_LONG.get(dm_char, '')
    ys_narr = NS_NARRATIVE.get(ys_name, '')
    rok_narr = ROKUSEI_NARRATIVE.get(rok_type, '')

    narr_cards = ''
    if dm_narr:
        narr_cards += f'''<div class="card" style="border-left:3px solid #6366f1">
      <div class="card-label" style="color:#a5b4fc">日主「{dm_char}」</div>
      <div style="font-size:13px;line-height:1.8;color:var(--text-secondary);margin-top:6px">{dm_narr}</div>
    </div>'''
    if ys_narr:
        narr_cards += f'''<div class="card" style="border-left:3px solid var(--accent-green)">
      <div class="card-label" style="color:#86efac">本命星「{ys_name}」</div>
      <div style="font-size:13px;line-height:1.8;color:var(--text-secondary);margin-top:6px">{ys_narr}</div>
    </div>'''
    if rok_narr:
        narr_cards += f'''<div class="card" style="border-left:3px solid #eab308">
      <div class="card-label" style="color:#fde047">六星占術「{rok_type}」</div>
      <div style="font-size:13px;line-height:1.8;color:var(--text-secondary);margin-top:6px">{rok_narr}</div>
    </div>'''
    narr_panel = f'''<div style="margin-top:16px">
    <div class="section-sub-title" style="font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--text-muted);margin-bottom:10px">命式の読み解き</div>
    <div class="grid grid-3">{narr_cards}</div>
  </div>''' if narr_cards else ''

    return f'''<section class="section" id="core-identity">
  {quote_html}
  {narr_panel}
  {insight_html}
  <div class="grid grid-4" style="margin-top:16px">
    <div class="card tc"><div class="card-label">本質</div>
      <div class="card-value">{essence_value}</div>
      <div class="card-sub">{essence_sub}</div></div>
    <div class="card tc"><div class="card-label">最強の軸</div>
      <div class="card-value">{axis_value}</div>
      <div class="card-sub">{axis_sub}</div></div>
    <div class="card tc"><div class="card-label">二面性</div>
      <div class="card-value">{dual_value}</div>
      <div class="card-sub">{dual_sub}</div></div>
    <div class="card tc"><div class="card-label">注意点</div>
      <div class="card-value" style="color:var(--yellow)">{watch_value}</div>
      <div class="card-sub">{watch_sub}</div></div>
  </div>
</section>'''

